WITH filtered AS (SELECT id, order_id, product_id, quantity, unit_price, LEAST(unit_price, quantity) AS least_unit_price_quantity FROM order_items WHERE product_id IS NOT NULL), filtered_order_items AS (SELECT *, least_unit_price_quantity + quantity AS least_unit_price_quantity_plus_quantity FROM filtered WHERE quantity = 3), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY least_unit_price_quantity, id) AS latest_rank FROM filtered_order_items QUALIFY latest_rank = 1), remaining_keys AS (SELECT id, product_id FROM deduped EXCEPT SELECT id, product_id FROM order_items WHERE order_id IN (1, 29, 31, 32)), reconciled AS (SELECT s.* FROM deduped s INNER JOIN remaining_keys k ON s.id = k.id AND s.product_id = k.product_id) SELECT id, order_id, product_id, quantity, unit_price, least_unit_price_quantity, least_unit_price_quantity_plus_quantity, latest_rank FROM reconciled ORDER BY unit_price, product_id
